(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"scalar":{"h":"WHAT YOU ARE LOOKING AT","t":"A **scalar** is a single number, such as the area of one house: **1200**. Everything in linear algebra is built up from numbers like this."},"vector":{"h":"A VECTOR IS A LIST OF NUMBERS","t":"Put several numbers in order and you get a **vector**. This house is **x = [1200, 2, 10]**: area, bedrooms and age together."},"dimensions":{"h":"THE DIMENSION COUNTS THE ENTRIES","t":"x has **3 entries** (area, bedrooms, age), so it is a **3-dimensional vector**."},"matrix":{"h":"STACK VECTORS INTO A MATRIX","t":"Stack **one vector per house** and you get a **matrix X**: a table of numbers."},"rows-columns":{"h":"ROWS ARE HOUSES, COLUMNS ARE FEATURES","t":"Each **row** is one house. Each **column** is one feature, measured for every house."},"transpose":{"h":"TRANSPOSE: SWAP ROWS AND COLUMNS","t":"The **transpose** flips the table: rows become columns and columns become rows."},"ml-dataset":{"h":"TAKEAWAY","t":"In machine learning a **dataset is a matrix of examples**: one row per example, one column per feature."}};
  // ── scene ──
  var steps = [
    { id: "scalar", label: "A scalar is one number", caption: "A scalar is a single number, such as the area of one house: 1200." },
    { id: "vector", label: "A vector is a list of numbers", caption: "Put several numbers in order and you get a vector. This house is x = [1200, 2, 10]." },
    { id: "dimensions", label: "The dimension counts the entries", caption: "x has 3 entries (area, bedrooms, age), so it is a 3-dimensional vector." },
    { id: "matrix", label: "Stack vectors into a matrix", caption: "Stack one vector per house and you get a matrix X: a table of numbers." },
    { id: "rows-columns", label: "Rows are houses, columns are features", caption: "Each row is one house. Each column is one feature, measured for every house." },
    { id: "transpose", label: "Transpose: swap rows and columns", caption: "The transpose flips the table: rows become columns and columns become rows." },
    { id: "ml-dataset", label: "A dataset is a matrix", caption: "In machine learning a dataset is a matrix of examples: one row per example, one column per feature." }
  ];

  var X = [[1200, 2, 10], [1800, 3, 4], [900, 1, 15]];
  var FEATURES = ["area", "bedrooms", "age"];
  var HOUSES = ["house 1", "house 2", "house 3"];

  var heading = txt(svg, 320, 48, "big", "", "middle");
  var footnote = txt(svg, 320, 334, "note", "", "middle");

  // One group per number. Positions change between steps.
  var cells = [];
  for (var r = 0; r < 3; r++) {
    cells.push([]);
    for (var c = 0; c < 3; c++) {
      var g = el("g", { class: "cell", opacity: 0 }, svg);
      el("rect", { x: 0, y: 0, width: 76, height: 42, rx: 7 }, g);
      txt(g, 38, 27, "cell-t", String(X[r][c]), "middle");
      cells[r].push(g);
    }
  }
  var rowLbl = [0, 1, 2].map(function () { return txt(svg, 196, 0, "lbl", "", "end"); });
  var colLbl = [0, 1, 2].map(function () { return txt(svg, 0, 100, "lbl", "", "middle"); });
  var bigX = txt(svg, 80, 188, "big", "", "middle");
  var tagRow = txt(svg, 214, 292, "lbl lbl-y", "", "start");
  var tagCol = txt(svg, 214, 312, "lbl lbl-g", "", "start");
  var brace = el("line", { x1: 204, y1: 214, x2: 204 + 3 * 86 - 10, y2: 214, stroke: "#e2b44a", "stroke-width": 2 }, svg);
  var braceTxt = txt(svg, 320, 238, "lbl lbl-y", "", "middle");

  function matPos(rr, cc) { return [214 + cc * 86, 112 + rr * 54]; }
  function vecPos(cc) { return [206 + cc * 86, 150]; }

  function layoutMatrix(transposed, labelsFor) {
    for (var rr = 0; rr < 3; rr++) {
      for (var cc = 0; cc < 3; cc++) {
        var p = transposed ? matPos(cc, rr) : matPos(rr, cc);
        place(cells[rr][cc], p[0], p[1]);
        show(cells[rr][cc], true);
      }
    }
    var rowsText = transposed ? FEATURES : HOUSES;
    var colsText = transposed ? HOUSES : FEATURES;
    if (labelsFor === "example") { rowsText = transposed ? ["feature 1", "feature 2", "feature 3"] : ["example 1", "example 2", "example 3"]; colsText = transposed ? ["example 1", "example 2", "example 3"] : ["feature 1", "feature 2", "feature 3"]; }
    for (var i = 0; i < 3; i++) {
      rowLbl[i].textContent = rowsText[i];
      rowLbl[i].setAttribute("y", matPos(i, 0)[1] + 27);
      colLbl[i].textContent = colsText[i];
      colLbl[i].setAttribute("x", matPos(0, i)[0] + 38);
      show(rowLbl[i], true);
      show(colLbl[i], true);
    }
  }

  function clearHighlights() {
    for (var rr = 0; rr < 3; rr++) for (var cc = 0; cc < 3; cc++) cells[rr][cc].setAttribute("class", "cell");
  }

  function render(index, id) {
    clearHighlights();
    heading.textContent = "";
    footnote.textContent = "";
    bigX.textContent = "";
    tagRow.textContent = "";
    tagCol.textContent = "";
    braceTxt.textContent = "";
    show(brace, false);
    for (var i = 0; i < 3; i++) { show(rowLbl[i], false); show(colLbl[i], false); }
    for (var rr = 0; rr < 3; rr++) for (var cc = 0; cc < 3; cc++) show(cells[rr][cc], false);

    if (id === "scalar") {
      heading.textContent = "scalar";
      place(cells[0][0], 282, 150);
      show(cells[0][0], true);
      footnote.textContent = "area = 1200   (one number)";
    } else if (id === "vector" || id === "dimensions") {
      heading.textContent = "vector  x = [1200, 2, 10]";
      for (var c2 = 0; c2 < 3; c2++) {
        place(cells[0][c2], vecPos(c2)[0], vecPos(c2)[1]);
        show(cells[0][c2], true);
        colLbl[c2].textContent = FEATURES[c2];
        colLbl[c2].setAttribute("x", vecPos(c2)[0] + 38);
        colLbl[c2].setAttribute("y", 138);
        show(colLbl[c2], true);
      }
      if (id === "dimensions") {
        show(brace, true);
        braceTxt.textContent = "3 entries  →  dimension 3";
      }
    } else if (id === "matrix") {
      for (var k = 0; k < 3; k++) colLbl[k].setAttribute("y", 100);
      layoutMatrix(false);
      bigX.textContent = "X =";
      footnote.textContent = "3 houses × 3 features  →  a 3 × 3 matrix";
    } else if (id === "rows-columns") {
      for (var k2 = 0; k2 < 3; k2++) colLbl[k2].setAttribute("y", 100);
      layoutMatrix(false);
      bigX.textContent = "X =";
      for (var a = 0; a < 3; a++) {
        cells[1][a].setAttribute("class", "cell hl-row");
        cells[a][0].setAttribute("class", "cell hl-col");
      }
      cells[1][0].setAttribute("class", "cell hl-both");
      tagRow.textContent = "row = one house";
      tagCol.textContent = "column = one feature";
    } else if (id === "transpose") {
      for (var k3 = 0; k3 < 3; k3++) colLbl[k3].setAttribute("y", 100);
      layoutMatrix(true);
      bigX.textContent = "Xᵀ =";
      footnote.textContent = "rows ↔ columns: the first row of Xᵀ is the area of every house";
    } else {
      for (var k4 = 0; k4 < 3; k4++) colLbl[k4].setAttribute("y", 100);
      layoutMatrix(false, "example");
      bigX.textContent = "X =";
      heading.textContent = "ML dataset = matrix of examples";
      footnote.textContent = "one row per example, one column per feature";
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
